SELECT id, type_id AS typeId, value_name AS valueName, sort, create_time AS createTime
FROM product_spec_value WHERE type_id = #{typeId}
ORDER BY sort ASC

SELECT id, type_id AS typeId, value_name AS valueName, sort, create_time AS createTime
FROM product_spec_value WHERE type_id = #{typeId} AND value_name = #{valueName}
LIMIT 1
